#include <iostream>

void	ft_draw_a(int a)
{
	int	mid;
	int	hight;
	int	i;
	int	j;
	int	len;

	mid = a / 2 + 1;
	hight = 4 * mid;
	i = 0;
	while (i < hight)
	{
		j = 0;
		while (j < hight - 1 - i)
		{
			std::cout << ' ';
			j++;
		}
		if (2 * i <= a || (i >= 2 * mid && i < 3 * mid))
		{
			len = 2 * i + a;
			j = 0;
			while (j < len)
			{
				std::cout << 'A';
				j++;
			}
		}
		else
		{
			j = 0;
			while (j < a)
			{
				std::cout << 'A';
				j++;
			}
			j = 0;
			while (j < 2 * i - a)
			{
				std::cout << ' ';
				j++;
			}
			j = 0;
			while (j < a)
			{
				std::cout << 'A';
				j++;
			}
		}
		std::cout << '\n';
		i++;
	}

}

int    main(void)
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int    n;

    while (std::cin >> n)
    {
        ft_draw_a(n);
        std::cout << '\n';
    }
    return (0);
}

