#include <iostream>

void	ft_calc_rectangle(int rectangle, int r_size, int times)
{
	int	nbr[10];
	int	i;
	int	j;
	int	k;
	int	*pnbr;

	pnbr = nbr;
	i = 9;
	while (i >= 0)
	{
		*pnbr = i;
		pnbr++;
		i--;
	}
	k = 0;
	while (k < rectangle)
	{
		if (k > 0)
			std::cout << '\n';
		pnbr = nbr;
		i = 0;
		while (i < r_size)
		{
			j = 0;
			while (j < times)
			{
				std::cout << *pnbr;
				pnbr++;
				if (pnbr == nbr + 10)
					pnbr = nbr;
				j++;
			}
			std::cout << '\n';
			i++;
		}
		k++;
	}
}

int	main(void)
{
	std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
	int	k,n,m;

	std::cin >> k >> n >> m;
	ft_calc_rectangle(k, n, m);
	return (0);
}
